INSERT INTO catalog_guides VALUES('arduino_uno',1,'en','{"intro":"UNO R3 is an ATmega328P development board. It has 14 digital I/O, 6 PWM-capable outputs and 6 analog inputs.","steps":["Start with USB power for this example; do not treat VIN, 5V and 3.3V as interchangeable terminals.","For an external LED example: D9 → 330 Ω resistor → LED anode; LED cathode → GND.","D9 is an example PWM output. A suitable sketch or predefined controller behavior is needed to drive it.","Use the official UNO R3 pinout to locate the physical headers and confirm your board revision."],"check":"This sheet describes UNO R3. UNO R4, clones and other board families can differ.","source":"https://docs.arduino.cc/hardware/uno-rev3/"}'::jsonb) ON CONFLICT DO NOTHING;
