INSERT INTO catalog_guides VALUES('arduino_nano',1,'en','{"intro":"Arduino Nano: a local connection reference with the catalog model’s terminal names and original documentation.","steps":["Identify the exact model, board revision and package printed on your part.","The catalog lists a typical 5 V supply. Verify which supply input this applies to; it does not specify the permitted voltage of every signal pin.","Select a terminal below to understand its function. Match signals by name, not by their position in this schematic.","Check signal direction and logic levels before wiring. Sensor, communication and display modules may need controller logic or configuration."],"check":"This is a functional catalog map, not a manufacturer package drawing. Where the exact variant is unknown, the physical pin order and absolute ratings are intentionally not inferred."}'::jsonb) ON CONFLICT DO NOTHING;
