INSERT INTO catalog_guides VALUES('hc_sr04',1,'en','{"intro":"An ultrasonic distance module: a trigger pulse starts a measurement, and the echo pulse carries the return time.","steps":["Supply the ELECFREAKS HC-SR04 module with 5 V and connect GND to the controller ground.","Example with UNO R3: connect TRIG to D9 and ECHO to D10. These GPIO choices are an example, not fixed module requirements.","The module requires a trigger pulse of at least 10 μs. Distance in cm is approximately echo time in μs ÷ 58.","Use suitable level shifting on ECHO before a 3.3 V-only controller input. Wiring alone does not generate measurements; controller logic is required."],"check":"The cited HC-SR04 variant specifies 2–400 cm. Board variants and real operating conditions can differ.","source":"https://www.elecfreaks.com/download/HC-SR04.pdf"}'::jsonb) ON CONFLICT DO NOTHING;
