INSERT INTO catalog_guides VALUES('led_red',1,'en','{"intro":"An LED emits light when forward current flows. A current-limiting resistor is part of the circuit, not an optional accessory.","steps":["Identify anode and cathode from the exact LED package. Do not rely on the model’s drawing as a physical pin-order reference.","Use a series resistor. Estimate R = (supply voltage − LED forward voltage) ÷ target current.","Connect the forward path through the resistor and return through the cathode for a single-colour LED.","RGB devices need the correct common-anode/common-cathode wiring and separate current limiting for each channel."],"check":"Forward voltage, current rating and RGB common terminal depend on the exact part number."}'::jsonb) ON CONFLICT DO NOTHING;
