INSERT INTO catalog_guides VALUES('l298n',1,'en','{"intro":"A dual H-bridge driver family for inductive loads. The L298 IC and an L298N breakout board are different reference levels.","steps":["Identify the exact breakout board and its jumper configuration before applying power.","Keep motor supply and logic supply requirements separate; connect the correct reference ground.","Connect motor leads to the relevant output pair and control inputs to compatible controller signals.","Check enable inputs, protection diodes, thermal limits and the board regulator before running a motor."],"check":"Chip limits are not guaranteed continuous ratings for a complete module. Never infer the breakout header layout from the chip package.","source":"https://www.st.com/resource/en/datasheet/l298.pdf"}'::jsonb) ON CONFLICT DO NOTHING;
